/* ===================== データ層 ===================== */
const SCHEMA_VERSION = 9;
const TRASH_RETENTION_DAYS = 30;
const NEW_ITEM_WINDOW_DAYS = 30;
const STATUS_ORDER = ["依頼", "見積提出", "受注", "工程", "請求", "入金済"];
const DEFAULT_CATEGORY_NAMES = ["シャッター本体", "部材・部品", "工事・作業", "諸経費"];

function uid(p) { return p + "_" + Date.now().toString(36) + Math.random().toString(36).slice(2, 6); }
function todayISO() { return new Date().toISOString().slice(0, 10); }
function nextMonthEndISO(dateStr) {
  if (!dateStr) return "";
  const [y, m] = dateStr.split("-").map(Number);
  const d = new Date(y, m + 1, 0);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}
function fmtDate(d) { if (!d) return "-"; const [y, m, day] = d.split("-"); return `${y}/${m}/${day}`; }
function fmtYen(n) { return "¥" + Math.round(Number(n) || 0).toLocaleString(); }

function seedCategories() {
  return DEFAULT_CATEGORY_NAMES.map((name, i) => ({ id: "cat_seed" + i, name, parentId: null }));
}
function seedPriceMaster() {
  const raw = [
    ["cat_seed0", "手動軽量シャッター 一式", "式", 180000],
    ["cat_seed0", "電動軽量シャッター 一式", "式", 380000],
    ["cat_seed0", "電動重量シャッター 一式", "式", 650000],
    ["cat_seed0", "グリルシャッター 一式", "式", 420000],
    ["cat_seed1", "スラット", "m", 8000],
    ["cat_seed1", "ガイドレール", "m", 6500],
    ["cat_seed1", "座板ゴム", "本", 4500],
    ["cat_seed1", "バランススプリング", "本", 12000],
    ["cat_seed1", "開閉機", "台", 95000],
    ["cat_seed1", "リモコン受信機", "台", 28000],
    ["cat_seed1", "押ボタンスイッチ", "個", 12000],
    ["cat_seed1", "障害物感知装置", "式", 45000],
    ["cat_seed1", "吊元金物", "式", 15000],
    ["cat_seed2", "既存シャッター撤去", "式", 35000],
    ["cat_seed2", "取付工事費", "式", 60000],
    ["cat_seed2", "電気配線工事", "式", 40000],
    ["cat_seed2", "点検・調整", "式", 15000],
    ["cat_seed2", "修理作業（1名1日）", "人工", 28000],
    ["cat_seed2", "夜間割増", "式", 20000],
    ["cat_seed3", "出張費", "式", 5000],
    ["cat_seed3", "廃材処分費", "式", 8000],
    ["cat_seed3", "運搬費", "式", 12000],
    ["cat_seed3", "現場管理費", "式", 25000],
  ];
  return raw.map((r, i) => ({ id: "pm_seed" + i, categoryId: r[0], name: r[1], unit: r[2], unitPrice: r[3], useCount: 0, costEntries: [], cautionNotes: [], cautionHeader: "" }));
}
function seedQuoteNoteTemplates() {
  const texts = [
    "本お見積りの有効期限は発行日より30日間です。",
    "現場調査の結果により、金額・工期が変動する場合がございます。",
    "工事期間は目安です。天候等により前後する場合がございます。",
    "別途、既存シャッターの状況により追加費用が発生する場合がございます。",
  ];
  return texts.map((t, i) => ({ id: "qnt_seed" + i, text: t }));
}
function seedData() {
  return {
    schemaVersion: SCHEMA_VERSION,
    counters: { quote: 1, invoice: 1 },
    categories: seedCategories(),
    priceMaster: seedPriceMaster(),
    quoteNoteTemplates: seedQuoteNoteTemplates(),
    projects: [],
    quotes: [],
    invoices: [],
  };
}

/* 既存データを消さずに新フィールドだけ足す（Firestore版：ミューテートしたコピーを返す） */
function migrate(data) {
  if (typeof data !== "object" || data === null) return seedData();
  const d = JSON.parse(JSON.stringify(data));
  if (!Array.isArray(d.projects)) d.projects = [];
  d.projects.forEach(p => {
    if (!Array.isArray(p.attachments)) p.attachments = [];
    if (typeof p.scheduledDate !== "string") p.scheduledDate = "";
    if (typeof p.scheduledTime !== "string") p.scheduledTime = "";
    if (typeof p.instructionMemo !== "string") p.instructionMemo = "";
    if (!Array.isArray(p.contacts)) {
      p.contacts = (p.siteContact || p.siteContactTel) ? [{ id: uid("contact"), name: p.siteContact || "", tel: p.siteContactTel || "" }] : [];
    }
    delete p.siteContact; delete p.siteContactTel;
    if (typeof p.parkingInfo !== "string") p.parkingInfo = "";
    if (!p.schedule || typeof p.schedule !== "object" || !Array.isArray(p.schedule.locations)) {
      p.schedule = { startDate: "", endDate: "", handoverDate: "", workTypes: [], timePatterns: [], locations: [], cells: {} };
    }
    if (typeof p.deletedAt === "undefined") p.deletedAt = null;
  });
  if (!Array.isArray(d.quotes)) d.quotes = [];
  d.quotes.forEach(q => {
    if (typeof q.isDraft !== "boolean") q.isDraft = false;
    if (typeof q.deletedAt === "undefined") q.deletedAt = null;
  });
  if (!Array.isArray(d.invoices)) d.invoices = [];
  d.invoices.forEach(inv => { if (typeof inv.deletedAt === "undefined") inv.deletedAt = null; });
  if (!d.counters) d.counters = { quote: 1, invoice: 1 };
  if (!Array.isArray(d.priceMaster) || d.priceMaster.length === 0) d.priceMaster = seedPriceMaster();
  if (!Array.isArray(d.categories) || d.categories.length === 0) d.categories = seedCategories();
  d.categories.forEach(c => { if (typeof c.parentId === "undefined") c.parentId = null; });
  let uncategorized = d.categories.find(c => c.name === "未分類" && c.parentId === null);
  d.priceMaster.forEach(m => {
    if (typeof m.useCount !== "number") m.useCount = 0;
    if (!Array.isArray(m.costEntries)) m.costEntries = [];
    if (!Array.isArray(m.cautionNotes)) m.cautionNotes = [];
    if (typeof m.cautionHeader !== "string") m.cautionHeader = "";
    if (!m.categoryId || !d.categories.find(c => c.id === m.categoryId)) {
      if (!uncategorized) { uncategorized = { id: "cat_uncat_" + Date.now().toString(36), name: "未分類", parentId: null }; d.categories.push(uncategorized); }
      m.categoryId = uncategorized.id;
    }
  });
  if (!Array.isArray(d.quoteNoteTemplates)) d.quoteNoteTemplates = seedQuoteNoteTemplates();
  // ゴミ箱：30日経過した削除済みデータを完全に削除
  const cutoff = Date.now() - TRASH_RETENTION_DAYS * 24 * 60 * 60 * 1000;
  d.projects = d.projects.filter(p => !p.deletedAt || new Date(p.deletedAt).getTime() > cutoff);
  d.quotes = d.quotes.filter(q => !q.deletedAt || new Date(q.deletedAt).getTime() > cutoff);
  d.invoices = d.invoices.filter(inv => !inv.deletedAt || new Date(inv.deletedAt).getTime() > cutoff);
  d.schemaVersion = SCHEMA_VERSION;
  return d;
}
function draftOf(db) { return JSON.parse(JSON.stringify(db)); }

/* ---- カテゴリ（階層）ヘルパー ---- */
function catById(db, id) { return db.categories.find(c => c.id === id); }
function catChildren(db, parentId) { return db.categories.filter(c => c.parentId === parentId); }
function catDescendantIds(db, id) {
  let ids = [id];
  catChildren(db, id).forEach(ch => { ids = ids.concat(catDescendantIds(db, ch.id)); });
  return ids;
}
function flattenCategoryTreeDepth(db, parentId, depth) {
  if (typeof parentId === "undefined") parentId = null;
  if (typeof depth === "undefined") depth = 0;
  let list = [];
  catChildren(db, parentId).forEach(c => {
    list.push({ id: c.id, name: c.name, depth });
    list = list.concat(flattenCategoryTreeDepth(db, c.id, depth + 1));
  });
  return list;
}
function ensureUncategorized(draft) {
  let u = draft.categories.find(c => c.name === "未分類" && c.parentId === null);
  if (!u) { u = { id: uid("cat"), name: "未分類", parentId: null }; draft.categories.push(u); }
  return u;
}

function getQuoteForProject(db, id, excludeDrafts) {
  let l = db.quotes.filter(q => q.projectId === id && !q.deletedAt);
  if (excludeDrafts) l = l.filter(q => !q.isDraft);
  return l[l.length - 1] || null;
}
function getInvoiceForProject(db, id) {
  const l = db.invoices.filter(i => i.projectId === id && !i.deletedAt);
  return l[l.length - 1] || null;
}
function calcTotals(items, taxRate = 0.10) {
  const subtotal = items.reduce((s, it) => s + (Number(it.qty) || 0) * (Number(it.unitPrice) || 0), 0);
  const tax = Math.round(subtotal * taxRate);
  return { subtotal, tax, total: subtotal + tax };
}
function nextQuoteNo(draft) { const n = draft.counters.quote++; return `Q-${new Date().getFullYear()}${String(n).padStart(4, "0")}`; }
function nextInvoiceNo(draft) { const n = draft.counters.invoice++; return `I-${new Date().getFullYear()}${String(n).padStart(4, "0")}`; }
function findQuotesUsingItem(db, { masterId, name }) {
  const hits = [];
  db.quotes.forEach(q => {
    q.items.forEach(it => {
      const match = (masterId && it.masterId === masterId) || (name && it.name === name);
      if (match) hits.push({ quote: q, item: it, project: db.projects.find(p => p.id === q.projectId) });
    });
  });
  return hits.sort((a, b) => (b.quote.date || "").localeCompare(a.quote.date || ""));
}
function blankItem() { return { id: uid("it"), name: "", unit: "式", qty: 1, unitPrice: 0 }; }
function escapeHtml(s) {
  if (s === null || s === undefined) return "";
  return String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}
function sanitizeFilename(s) { return String(s || "").replace(/[\\/:*?"<>|\s]+/g, "_"); }

/* ===================== Firebase Storage（添付ファイル） ===================== */
async function ebUploadFile(file, pathPrefix) {
  const path = `estimateBilling/${pathPrefix}/${uid("f")}_${file.name}`;
  const storageRef = ref(storage, path);
  await uploadBytes(storageRef, file);
  const fileUrl = await getDownloadURL(storageRef);
  return { fileUrl, storagePath: path, fileName: file.name, fileType: file.type, createdAt: todayISO() };
}
async function ebDeleteFile(storagePath) {
  if (!storagePath) return;
  try { await deleteObject(ref(storage, storagePath)); } catch { /* 既に無い場合等は無視 */ }
}
const MAX_FILE_SIZE = 4 * 1024 * 1024;

