/* ---------- 見積タブ ---------- */
function QuotesTab({ ctx, search, setSearch }) {
  const { db, open, confirm } = ctx;
  const kw = search.trim();
  let quotes = db.quotes.filter(q => !q.deletedAt).slice().sort((a, b) => (b.date || "").localeCompare(a.date || ""));
  let matchInfo = {};
  if (kw) {
    quotes = quotes.filter(q => {
      const p = db.projects.find(x => x.id === q.projectId);
      const inSite = p && (p.siteName.includes(kw) || p.customerName.includes(kw));
      const hitItems = q.items.filter(it => it.name && it.name.includes(kw));
      if (hitItems.length) matchInfo[q.id] = hitItems;
      return inSite || hitItems.length > 0;
    });
  }
  function del(q) {
    const usedByInvoice = db.invoices.some(inv => inv.quoteId === q.id && !inv.deletedAt);
    const msg = q.isDraft ? "この下書きを削除しますか？" : `この見積（${q.quoteNo}）を削除しますか？${usedByInvoice ? "\n※この見積をもとにした請求書がありますが、請求書自体は削除されません。" : ""}`;
    confirm(msg, () => { const d = draftOf(db); d.quotes = d.quotes.filter(x => x.id !== q.id); ctx.save(d); });
  }
  return (
    <>
      <input type="search" value={search} placeholder="現場名・取引先・見積項目で検索" onChange={e => setSearch(e.target.value)} />
      <div style={{ height: 12 }}></div>
      {db.quotes.length === 0
        ? <div className="empty">見積書はまだありません。<br />案件タブから作成してください。</div>
        : quotes.length === 0
          ? <div className="empty">「{kw}」に一致する見積はありません。</div>
          : quotes.map(q => {
            const p = db.projects.find(x => x.id === q.projectId);
            const hits = matchInfo[q.id];
            return (
              <div className="card" key={q.id}>
                <div className="card-top">
                  <div><div className="card-title">{p ? p.siteName : "(案件不明)"} {q.isDraft && <span className="draft-badge" style={{ margin: "0 0 0 4px" }}>下書き</span>}</div>
                    <div className="card-sub">{p ? p.customerName : ""}・{q.isDraft ? "番号未確定" : q.quoteNo}・{fmtDate(q.date)}</div></div>
                  <div className="card-title">{fmtYen(q.total)}</div>
                </div>
                {hits && <div className="hit">該当: {hits.map(it => `${it.name} ${fmtYen(it.unitPrice)}/${it.unit || ""}`).join(" ／ ")}</div>}
                <div className="card-actions">
                  <button className="btn secondary small" onClick={() => open("quoteView", { quote: q })}>見る</button>
                  <button className="btn secondary small" onClick={() => open("quoteEditor", { quote: q, projectId: q.projectId })}>編集</button>
                  <button className="btn ghost small" onClick={() => open("projectPickerForCopy", { pickedQuote: q })}>コピーして新規</button>
                  <button className="btn ghost small danger-text" onClick={() => del(q)}>削除</button>
                </div>
              </div>
            );
          })}
    </>
  );
}
function QuoteEditorSheet({ ctx, quote, projectId, onClose }) {
  const { db, save, confirm, open, notice } = ctx;
  const isNew = !quote;
  const project = db.projects.find(p => p.id === projectId);
  const base = quote ? db.quotes.find(x => x.id === quote.id) || quote : { id: null, projectId, quoteNo: null, date: todayISO(), items: [blankItem()], notes: "", isDraft: false };
  const [date, setDate] = useState(base.date);
  const [items, setItems] = useState(withMasterInfo(base.items, db));
  const [notes, setNotes] = useState(base.notes || "");
  const isDraft = !!base.isDraft;
  const showDraftBtn = isNew || isDraft;

  function syncedDoc() { return { ...base, date, notes, items: stripMasterInfo(items), ...calcTotals(stripMasterInfo(items)) }; }
  function doSaveDraft() {
    const d = draftOf(db);
    const q = syncedDoc(); q.isDraft = true;
    if (!q.id) { q.id = uid("quote"); d.quotes.push(q); } else Object.assign(d.quotes.find(x => x.id === q.id), q);
    save(d);
    notice("一時保存しました。続きはあとで「見積」タブから編集できます。");
  }
  function doSaveFinal() {
    const d = draftOf(db);
    const q = syncedDoc();
    if (!q.id) { q.id = uid("quote"); d.quotes.push(q); } else Object.assign(d.quotes.find(x => x.id === q.id), q);
    if (!q.quoteNo) q.quoteNo = nextQuoteNo(d);
    q.isDraft = false;
    Object.assign(d.quotes.find(x => x.id === q.id), q);
    const p = d.projects.find(x => x.id === q.projectId);
    if (p && p.status === "依頼") p.status = "見積提出";
    save(d);
    onClose();
  }
  function handleSaveClick() {
    if (!notes.trim()) confirm("備考が入力されていません。このまま保存しますか？\n（有効期限や注意事項の書き忘れがないか確認してください）", doSaveFinal);
    else doSaveFinal();
  }
  function handleMasterAdd(newItems) {
    setItems(prev => {
      const base2 = (prev.length === 1 && !prev[0].name && !Number(prev[0].unitPrice)) ? [] : prev;
      return [...base2, ...withMasterInfo(newItems, db)];
    });
  }

  return (
    <>
      <SheetHead title={isNew ? "見積作成" : "見積を編集"} onClose={onClose} />
      {isDraft && <div className="draft-badge">下書き（まだ確定していません）</div>}
      <div className="card-sub" style={{ marginBottom: 10 }}>{project ? project.siteName : ""} / {project ? project.customerName : ""}</div>
      <div style={{ display: "flex", gap: 8 }}>
        <button className="btn secondary small" style={{ flex: 1 }} onClick={() => ctx.open2("masterPicker", { onAdd: handleMasterAdd })}>マスタから積み上げ</button>
        {isNew && <button className="btn ghost small" style={{ flex: 1 }} onClick={() => ctx.open2("pastQuotePicker", {
          onPick: picked => { setItems(withMasterInfo(picked.items.map(it => ({ ...it, id: uid("it") })), db)); setNotes(picked.notes); }
        })}>過去の見積からコピー</button>}
      </div>
      <Field label="見積日"><input type="date" value={date} onChange={e => setDate(e.target.value)} /></Field>
      <ItemsEditor items={items} setItems={setItems} />
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 12 }}>
        <label style={{ margin: 0 }}>備考</label>
        <button className="btn secondary small" onClick={() => ctx.open2("quoteNoteTemplatePicker", { onPick: text => setNotes(prev => prev.trim() ? prev.trim() + "\n" + text : text) })}>定型文を挿入</button>
      </div>
      <textarea value={notes} onChange={e => setNotes(e.target.value)} />
      <div className="sheet-footer">
        <button className="btn secondary" onClick={onClose}>キャンセル</button>
        {showDraftBtn && <button className="btn ghost" onClick={doSaveDraft}>一時保存</button>}
        <button className="btn" onClick={handleSaveClick}>{isDraft ? "確定して保存" : "保存"}</button>
      </div>
    </>
  );
}
function QuoteNoteTemplatePickerSheet({ ctx, onPick, onClose }) {
  const { db, save, confirm } = ctx;
  const [newText, setNewText] = useState("");
  const tpls = db.quoteNoteTemplates || [];
  function use(t) { onPick(t.text); onClose(); }
  function del(id) { confirm("この定型文を削除しますか？", () => { const d = draftOf(db); d.quoteNoteTemplates = (d.quoteNoteTemplates || []).filter(t => t.id !== id); save(d); }); }
  function add() { const text = newText.trim(); if (!text) return; const d = draftOf(db); d.quoteNoteTemplates = d.quoteNoteTemplates || []; d.quoteNoteTemplates.push({ id: uid("qnt"), text }); save(d); setNewText(""); }
  return (
    <>
      <SheetHead title="定型文を挿入" onClose={onClose} />
      {tpls.length === 0 ? <div className="empty">定型文がまだありません。<br />下から登録してください。</div> : tpls.map(t => (
        <div className="past-pick" key={t.id}>
          <div className="pp-name" style={{ whiteSpace: "pre-wrap", flex: 1 }}>{t.text}</div>
          <div style={{ display: "flex", gap: 6 }}><button className="btn secondary small" onClick={() => use(t)}>使う</button><button className="icon-btn danger" onClick={() => del(t.id)}>✕</button></div>
        </div>
      ))}
      <div className="sticky-actions">
        <textarea value={newText} placeholder="新しい定型文を入力" onChange={e => setNewText(e.target.value)} />
        <button className="btn ghost small" style={{ width: "100%", marginTop: 6 }} onClick={add}>＋ 定型文として登録</button>
      </div>
    </>
  );
}
