function MasterTab({ ctx, filter, setFilter }) {
  const { db, open } = ctx;
  const [search, setSearch] = useState("");
  const roots = catChildren(db, null);
  const newItemCutoff = Date.now() - NEW_ITEM_WINDOW_DAYS * 24 * 60 * 60 * 1000;
  const newItems = db.priceMaster.filter(m => m.createdAt && new Date(m.createdAt).getTime() > newItemCutoff).sort((a, b) => (b.createdAt || "").localeCompare(a.createdAt || ""));
  const chipDefs = [{ id: "all", name: "すべて" }, { id: "__new__", name: `新項目${newItems.length ? `（${newItems.length}）` : ""}` }, ...roots.map(c => ({ id: c.id, name: c.name }))];
  const allowedIds = filter === "all" ? null : catDescendantIds(db, filter);
  const tree = flattenCategoryTreeDepth(db, null, 0);
  const nodesToShow = tree.filter(node => !allowedIds || allowedIds.includes(node.id));
  const kw = search.trim();

  function MasterRow({ m, categoryLabel }) {
    const usedIn = findQuotesUsingItem(db, { masterId: m.id, name: m.name }).length;
    const costCount = (m.costEntries || []).length;
    const cautionCount = (m.cautionNotes || []).length;
    return (
      <div className="master-row" onClick={() => open("masterItemEditor", { item: m })}>
        <div className="m-body">
          <div className="m-name">{m.name}</div>
          <div className="m-sub">{categoryLabel ? `${categoryLabel}・` : ""}単位: {m.unit || "-"}{usedIn ? `・過去見積 ${usedIn}件` : ""}</div>
        </div>
        <div className="m-price">{fmtYen(m.unitPrice)}</div>
        <button className="btn secondary small cost-btn" onClick={e => { e.stopPropagation(); open("costInfo", { m }); }}>下代{costCount ? `（${costCount}）` : ""}</button>
        <button className="btn secondary small caution-btn" onClick={e => { e.stopPropagation(); open("cautionInfo", { m }); }}>注意{cautionCount ? `（${cautionCount}）` : ""}</button>
      </div>
    );
  }

  return (
    <>
      <input type="search" value={search} placeholder="項目名で検索（カテゴリをまたいで探せます）" onChange={e => setSearch(e.target.value)} />
      <div style={{ height: 10 }}></div>
      {kw ? (() => {
        const hits = db.priceMaster.filter(m => m.name.includes(kw));
        if (hits.length === 0) return <div className="empty">「{kw}」に一致する項目はありません。</div>;
        return hits.map(m => {
          const cat = catById(db, m.categoryId);
          return <MasterRow key={m.id} m={m} categoryLabel={cat ? cat.name : "未分類"} />;
        });
      })() : <>
        <div className="filter-chips">{chipDefs.map(c => <div key={c.id} className={`chip${filter === c.id ? " active" : ""}`} onClick={() => setFilter(c.id)}>{c.name}</div>)}</div>
        {filter === "__new__" ? (
          <>
            <div className="card-sub" style={{ marginBottom: 8 }}>直近{NEW_ITEM_WINDOW_DAYS}日以内に登録した項目です（登録先カテゴリはそのまま・{NEW_ITEM_WINDOW_DAYS}日経つとここから消えます）。</div>
            {newItems.length === 0
              ? <div className="empty">直近{NEW_ITEM_WINDOW_DAYS}日以内に登録した項目はありません。</div>
              : newItems.map(m => {
                const cat = catById(db, m.categoryId);
                return <MasterRow key={m.id} m={m} categoryLabel={cat ? cat.name : "未分類"} />;
              })}
          </>
        ) : <>
          <button className="btn ghost small" style={{ width: "100%", marginBottom: 4 }} onClick={() => open("categoryManager", {})}>カテゴリを編集</button>
          {nodesToShow.length === 0
            ? <div className="empty">カテゴリがありません。<br />「カテゴリを編集」から作成してください。</div>
            : nodesToShow.map(node => {
              const items = db.priceMaster.filter(m => m.categoryId === node.id);
              return (
                <div key={node.id}>
                  <div className="cat-head" style={{ paddingLeft: node.depth * 14 }}>{node.name}</div>
                  {items.length === 0
                    ? <div className="card-sub" style={{ paddingLeft: node.depth * 14 + 4, margin: "2px 0 8px" }}>（この中にはまだ項目がありません）</div>
                    : items.map(m => <MasterRow key={m.id} m={m} />)}
                </div>
              );
            })}
        </>}
      </>}
    </>
  );
}
function CategoryMoveTargetSheet({ ctx, categoryId, onMoved, onClose }) {
  const { db } = ctx;
  const cat = catById(db, categoryId);
  const blockedIds = catDescendantIds(db, categoryId); // 自分自身と子孫には移動できない
  const candidates = flattenCategoryTreeDepth(db, null, 0).filter(node => !blockedIds.includes(node.id));
  function pick(newParentId) { onClose(); onMoved(newParentId); }
  return (
    <>
      <SheetHead title={`「${cat ? cat.name : ""}」の移動先を選択`} onClose={onClose} />
      <div className="card-sub" style={{ marginBottom: 8 }}>選んだカテゴリの中に、このカテゴリごと（中の項目・子カテゴリも一緒に）移動します。</div>
      <div className="past-pick">
        <div className="pp-name">トップレベルにする</div>
        <button className="btn secondary small" disabled={cat && cat.parentId === null} onClick={() => pick(null)}>選択</button>
      </div>
      {candidates.map(node => (
        <div className="past-pick" key={node.id}>
          <div className="pp-name">{"　".repeat(node.depth)}{node.name}</div>
          <button className="btn secondary small" disabled={cat && cat.parentId === node.id} onClick={() => pick(node.id)}>選択</button>
        </div>
      ))}
    </>
  );
}
function CategoryManagerSheet({ ctx, onClose }) {
  const { db, save, confirm, notice } = ctx;
  const [addingChildParent, setAddingChildParent] = useState(null);
  const [newChildName, setNewChildName] = useState("");
  const [newCat, setNewCat] = useState("");
  const tree = flattenCategoryTreeDepth(db, null, 0);

  function rename(id, name) {
    const cat = catById(db, id);
    const newName = name.trim();
    if (!newName || newName === cat.name) return;
    const dupe = catChildren(db, cat.parentId).find(c => c.id !== id && c.name === newName);
    if (dupe) { notice("同じ階層に同じ名前のカテゴリがあります"); return; }
    const d = draftOf(db); d.categories.find(c => c.id === id).name = newName; save(d);
  }
  function move(id, dir) {
    const d = draftOf(db);
    const cat = catById(d, id);
    const siblings = catChildren(d, cat.parentId);
    const i = siblings.findIndex(c => c.id === id);
    const j = i + dir;
    if (j < 0 || j >= siblings.length) return;
    const other = siblings[j];
    const a = d.categories.indexOf(d.categories.find(c => c.id === cat.id)), b = d.categories.indexOf(d.categories.find(c => c.id === other.id));
    [d.categories[a], d.categories[b]] = [d.categories[b], d.categories[a]];
    save(d);
  }
  function addChild(parentId, name) {
    const n = name.trim(); if (!n) return;
    const dupe = catChildren(db, parentId).find(c => c.name === n);
    if (dupe) { notice("同じ階層に同じ名前のカテゴリがあります"); return; }
    const d = draftOf(db); d.categories.push({ id: uid("cat"), name: n, parentId }); save(d);
    setAddingChildParent(null); setNewChildName("");
  }
  function del(id) {
    const cat = catById(db, id);
    const children = catChildren(db, id);
    const count = db.priceMaster.filter(m => m.categoryId === id).length;
    let msg = `「${cat.name}」を削除しますか？`;
    if (count > 0) msg += `\n中の項目 ${count}件は「未分類」に移動します。`;
    if (children.length > 0) msg += `\n下にある子カテゴリ ${children.length}件は1つ上の階層に移動します。`;
    confirm(msg, () => {
      const d = draftOf(db);
      const dcat = catById(d, id);
      if (count > 0) { const uncat = ensureUncategorized(d); d.priceMaster.forEach(m => { if (m.categoryId === id) m.categoryId = uncat.id; }); }
      catChildren(d, id).forEach(ch => { ch.parentId = dcat.parentId; });
      d.categories = d.categories.filter(c => c.id !== id);
      save(d);
    });
  }
  function addTop() {
    const n = newCat.trim(); if (!n) return;
    const d = draftOf(db); d.categories.push({ id: uid("cat"), name: n, parentId: null }); save(d); setNewCat("");
  }
  function moveTo(id, newParentId) {
    const cat = catById(db, id);
    if (cat.parentId === newParentId) return;
    const dupe = catChildren(db, newParentId).find(c => c.name === cat.name);
    if (dupe) { notice("移動先に同じ名前のカテゴリがあります"); return; }
    const d = draftOf(db); d.categories.find(c => c.id === id).parentId = newParentId; save(d);
  }

  return (
    <>
      <SheetHead title="カテゴリを編集" onClose={onClose} />
      <div className="card-sub" style={{ marginBottom: 8 }}>「＋子」でそのカテゴリの中にさらにカテゴリを作れます。「移動」で別の階層に丸ごと移せます。名前を書き換えても中の項目はそのまま残ります。</div>
      {tree.map(node => {
        const count = db.priceMaster.filter(m => m.categoryId === node.id).length;
        const siblings = catChildren(db, catById(db, node.id).parentId);
        const idx = siblings.findIndex(c => c.id === node.id);
        return (
          <div key={node.id}>
            <div className="cat-edit-row" style={{ paddingLeft: node.depth * 16, flexWrap: "wrap" }}>
              <input type="text" defaultValue={node.name} className="cat-name" onBlur={e => rename(node.id, e.target.value)} />
              <span style={{ fontSize: 11, color: "var(--sub)", whiteSpace: "nowrap" }}>{count}件</span>
              <button className="icon-btn" disabled={idx === 0} onClick={() => move(node.id, -1)}>▲</button>
              <button className="icon-btn" disabled={idx === siblings.length - 1} onClick={() => move(node.id, 1)}>▼</button>
              <button className="icon-btn" onClick={() => { setAddingChildParent(p => p === node.id ? null : node.id); setNewChildName(""); }}>＋子</button>
              <button className="btn secondary small" onClick={() => ctx.open2("categoryMoveTarget", { categoryId: node.id, onMoved: newParentId => moveTo(node.id, newParentId) })}>移動</button>
              <button className="icon-btn danger" onClick={() => del(node.id)}>✕</button>
            </div>
            {addingChildParent === node.id && (
              <div className="cat-edit-row" style={{ paddingLeft: (node.depth + 1) * 16 }}>
                <input type="text" value={newChildName} placeholder={`「${node.name}」の中に作るカテゴリ名`} onChange={e => setNewChildName(e.target.value)} />
                <button className="icon-btn" onClick={() => addChild(node.id, newChildName)}>追加</button>
                <button className="icon-btn" onClick={() => setAddingChildParent(null)}>×</button>
              </div>
            )}
          </div>
        );
      })}
      <div style={{ display: "flex", gap: 6, marginTop: 14 }}>
        <input type="text" value={newCat} placeholder="新しいカテゴリ名（トップレベル）" onChange={e => setNewCat(e.target.value)} />
        <button className="btn" style={{ whiteSpace: "nowrap" }} onClick={addTop}>追加</button>
      </div>
      <div className="sheet-footer"><button className="btn secondary" onClick={onClose}>完了</button></div>
    </>
  );
}
function MasterItemEditorSheet({ ctx, item, onSaved, onClose }) {
  const { db, save, confirm, notice, open } = ctx;
  const isNew = !item;
  const m = item ? db.priceMaster.find(x => x.id === item.id) || item : { id: null, categoryId: (catChildren(db, null)[0] && catChildren(db, null)[0].id) || null, name: "", unit: "式", unitPrice: 0, useCount: 0, costEntries: [], cautionNotes: [], cautionHeader: "" };
  const usage = isNew ? [] : findQuotesUsingItem(db, { masterId: m.id, name: m.name });
  const [categoryId, setCategoryId] = useState(m.categoryId);
  const [newCatMode, setNewCatMode] = useState(false);
  const [newCatName, setNewCatName] = useState("");
  const [name, setName] = useState(m.name);
  const [unit, setUnit] = useState(m.unit || "");
  const [price, setPrice] = useState(m.unitPrice);
  const tree = flattenCategoryTreeDepth(db, null, 0);
  const siblings = !isNew ? db.priceMaster.filter(x => x.categoryId === m.categoryId) : [];
  const idx = !isNew ? siblings.findIndex(x => x.id === m.id) : -1;

  function move(dir) {
    const d = draftOf(db);
    const dm = d.priceMaster.find(x => x.id === m.id);
    const sib = d.priceMaster.filter(x => x.categoryId === dm.categoryId);
    const i = sib.findIndex(x => x.id === dm.id); const j = i + dir;
    if (j < 0 || j >= sib.length) return;
    const other = sib[j];
    const a = d.priceMaster.indexOf(dm), b = d.priceMaster.indexOf(d.priceMaster.find(x => x.id === other.id));
    [d.priceMaster[a], d.priceMaster[b]] = [d.priceMaster[b], d.priceMaster[a]];
    save(d);
  }
  function handleDelete() {
    confirm("この項目を削除しますか？（作成済みの見積・請求には影響しません）", () => {
      const d = draftOf(db); d.priceMaster = d.priceMaster.filter(x => x.id !== m.id); save(d); onClose();
    });
  }
  function handleSave() {
    const nm = name.trim();
    if (!nm) { notice("項目名を入力してください"); return; }
    const d = draftOf(db);
    let catId = categoryId;
    if (newCatMode) {
      const nn = newCatName.trim();
      if (!nn) { notice("新しいカテゴリ名を入力してください"); return; }
      const dupe = catChildren(d, null).find(c => c.name === nn);
      if (dupe) catId = dupe.id;
      else { catId = uid("cat"); d.categories.push({ id: catId, name: nn, parentId: null }); }
    }
    const fields = { categoryId: catId, name: nm, unit: unit.trim(), unitPrice: Number(price) || 0 };
    let saved;
    if (isNew) { saved = { ...m, ...fields, id: uid("pm"), createdAt: todayISO() }; d.priceMaster.push(saved); }
    else { saved = Object.assign(d.priceMaster.find(x => x.id === m.id), fields); }
    save(d);
    if (onSaved) { onClose(); onSaved(saved); } else onClose();
  }

  return (
    <>
      <SheetHead title={isNew ? "マスタに項目を追加" : "項目を編集"} onClose={onClose} />
      <Field label="カテゴリ">
        <select value={newCatMode ? "__new__" : categoryId} onChange={e => { if (e.target.value === "__new__") setNewCatMode(true); else { setNewCatMode(false); setCategoryId(e.target.value); } }}>
          {tree.map(c => <option key={c.id} value={c.id}>{"　".repeat(c.depth)}{c.name}</option>)}
          <option value="__new__">＋ 新しいカテゴリを作る（トップレベル）</option>
        </select>
      </Field>
      {newCatMode && <Field label="新しいカテゴリ名"><input type="text" value={newCatName} placeholder="例）電装部品" onChange={e => setNewCatName(e.target.value)} /></Field>}
      {!isNew && (
        <Field label="この項目の並び順（同じカテゴリ内）">
          <div style={{ display: "flex", gap: 8 }}>
            <button className="btn secondary small" style={{ flex: 1 }} disabled={idx <= 0} onClick={() => move(-1)}>▲ 上へ</button>
            <button className="btn secondary small" style={{ flex: 1 }} disabled={idx >= siblings.length - 1} onClick={() => move(1)}>▼ 下へ</button>
          </div>
        </Field>
      )}
      <Field label="項目名"><input type="text" value={name} placeholder="例）ガイドレール" onChange={e => setName(e.target.value)} /></Field>
      <Field label="単位"><input type="text" value={unit} placeholder="式 / m / 台 / 人工" onChange={e => setUnit(e.target.value)} /></Field>
      <Field label="標準単価"><input type="number" value={price} min="0" onChange={e => setPrice(e.target.value)} /></Field>
      {!isNew && <>
        <button className="btn secondary" style={{ width: "100%", marginTop: 16 }} onClick={() => open("itemUsage", { m })}>この項目を使った過去見積を見る（{usage.length}件）</button>
        <button className="btn secondary" style={{ width: "100%", marginTop: 8 }} onClick={() => open("costInfo", { m })}>下代情報を見る（{(m.costEntries || []).length}件）</button>
        <button className="btn secondary" style={{ width: "100%", marginTop: 8 }} onClick={() => open("cautionInfo", { m })}>注意事項を見る（{(m.cautionNotes || []).length}件）</button>
      </>}
      <div className="sheet-footer">
        {!isNew && <button className="btn ghost" onClick={handleDelete}>削除</button>}
        <button className="btn" onClick={handleSave}>保存</button>
      </div>
    </>
  );
}
function ItemUsageSheet({ ctx, m, onClose }) {
  const { db, open } = ctx;
  const hits = findQuotesUsingItem(db, { masterId: m.id, name: m.name });
  let stats = null;
  if (hits.length) {
    const prices = hits.map(h => Number(h.item.unitPrice) || 0);
    const min = Math.min(...prices), max = Math.max(...prices), avg = prices.reduce((a, b) => a + b, 0) / prices.length;
    stats = (
      <div className="stat-bar">
        <div className="stat-box"><div className="sv">{fmtYen(min)}</div><div className="sl">最安</div></div>
        <div className="stat-box"><div className="sv">{fmtYen(avg)}</div><div className="sl">平均</div></div>
        <div className="stat-box"><div className="sv">{fmtYen(max)}</div><div className="sl">最高</div></div>
      </div>
    );
  }
  return (
    <>
      <SheetHead title={`「${m.name}」を使った見積`} onClose={onClose} />
      {stats}
      {hits.length === 0 ? <div className="empty">この項目を使った見積はまだありません。</div> : hits.map((h, i) => (
        <div className="past-pick" key={i}>
          <div style={{ minWidth: 0 }}>
            <div className="pp-name">{h.project ? h.project.siteName : "(案件不明)"}</div>
            <div className="pp-sub">{h.project ? h.project.customerName : ""}・{fmtDate(h.quote.date)}・{h.quote.quoteNo}</div>
            <div className="pp-sub" style={{ color: "var(--text)", marginTop: 2 }}>{fmtYen(h.item.unitPrice)} / {h.item.unit || ""} × {h.item.qty}　→　{fmtYen((Number(h.item.qty) || 0) * (Number(h.item.unitPrice) || 0))}</div>
          </div>
          <button className="btn secondary small" onClick={() => { onClose(); open("quoteView", { quote: h.quote }); }}>見積を見る</button>
        </div>
      ))}
    </>
  );
}
function FileEntryPreview({ e }) {
  if (!e.fileUrl) return null;
  const isImage = e.fileType && e.fileType.startsWith("image/");
  return <div className="ce-file">{isImage ? <a href={e.fileUrl} target="_blank" rel="noreferrer"><img src={e.fileUrl} alt={e.fileName || ""} /></a> : <a href={e.fileUrl} target="_blank" rel="noreferrer" className="ce-file-link">📎 {e.fileName || "添付ファイル"}</a>}</div>;
}
function CostInfoSheet({ ctx, m, onClose }) {
  const { db, save, confirm, open } = ctx;
  const cur = db.priceMaster.find(x => x.id === m.id) || m;
  const entries = (cur.costEntries || []).slice().sort((a, b) => (b.createdAt || "").localeCompare(a.createdAt || ""));
  let marginLine = null;
  if (entries.length) {
    const latest = entries[0];
    if (Number(latest.price) > 0 && cur.unitPrice > 0) {
      const margin = cur.unitPrice - Number(latest.price);
      const marginPct = Math.round((margin / cur.unitPrice) * 100);
      marginLine = <div className="card-sub" style={{ marginBottom: 10 }}>売価 {fmtYen(cur.unitPrice)} － 最新の下代 {fmtYen(latest.price)} ＝ 粗利 {fmtYen(margin)}（{marginPct}%）</div>;
    }
  }
  function del(e) {
    confirm("この下代情報を削除しますか？", () => {
      const d = draftOf(db);
      const dm = d.priceMaster.find(x => x.id === m.id);
      dm.costEntries = (dm.costEntries || []).filter(x => x.id !== e.id);
      save(d);
      ebDeleteFile(e.storagePath);
    });
  }
  return (
    <>
      <SheetHead title="下代情報" onClose={onClose} />
      <div className="card-sub" style={{ marginBottom: 12 }}>{cur.name}（現在の売価: {fmtYen(cur.unitPrice)} / {cur.unit || ""}）</div>
      {entries.length === 0 ? <div className="empty">下代情報はまだありません。<br />「＋ 下代情報を追加」から登録してください。</div> : <>
        {marginLine}
        {entries.map(e => (
          <div className="cost-entry" key={e.id}>
            <div className="ce-top"><div className="ce-price">{fmtYen(e.price)}</div><button className="icon-btn danger" onClick={() => del(e)}>✕</button></div>
            <div className="ce-meta">{e.supplier ? `仕入先: ${e.supplier}　` : ""}{fmtDate(e.createdAt)}</div>
            {e.note && <div className="ce-note">{e.note}</div>}
            <FileEntryPreview e={e} />
          </div>
        ))}
      </>}
      <div className="sticky-actions"><button className="btn" style={{ width: "100%" }} onClick={() => ctx.open2("costEntryForm", { m: cur })}>＋ 下代情報を追加</button></div>
    </>
  );
}
function CostEntryFormSheet({ ctx, m, onSaved, onClose }) {
  const { db, save, notice } = ctx;
  const [price, setPrice] = useState("");
  const [supplier, setSupplier] = useState("");
  const [note, setNote] = useState("");
  const [uploading, setUploading] = useState(false);
  const fileRef = useRef(null);

  async function handleSave() {
    const file = fileRef.current && fileRef.current.files[0];
    if (file && file.size > MAX_FILE_SIZE) { notice("ファイルサイズが大きすぎます（4MBまで）。写真は少し圧縮してから添付してください。"); return; }
    setUploading(true);
    try {
      let fileMeta = { fileUrl: null, storagePath: null, fileName: null, fileType: null };
      if (file) fileMeta = await ebUploadFile(file, `costEntries/${m.id}`);
      const d = draftOf(db);
      const dm = d.priceMaster.find(x => x.id === m.id);
      dm.costEntries = dm.costEntries || [];
      dm.costEntries.push({ id: uid("cost"), price: Number(price) || 0, supplier: supplier.trim(), note: note.trim(), ...fileMeta, createdAt: todayISO() });
      save(d);
      onClose();
      if (onSaved) onSaved();
    } catch (err) { notice("ファイルのアップロードに失敗しました: " + err.message); }
    setUploading(false);
  }
  return (
    <>
      <SheetHead title="下代情報を追加" onClose={onClose} />
      <div className="card-sub" style={{ marginBottom: 8 }}>{m.name}</div>
      <Field label="下代単価"><input type="number" min="0" placeholder="例）6000" value={price} onChange={e => setPrice(e.target.value)} /></Field>
      <Field label="仕入先（任意）"><input type="text" placeholder="例）〇〇建材" value={supplier} onChange={e => setSupplier(e.target.value)} /></Field>
      <Field label="メモ（任意）"><textarea placeholder="ロット条件、値上げ情報など" value={note} onChange={e => setNote(e.target.value)} /></Field>
      <Field label="ファイル添付（任意・見積書の写真など）"><input ref={fileRef} type="file" accept="image/*,.pdf" disabled={uploading} /></Field>
      <div className="sheet-footer">
        <button className="btn secondary" onClick={onClose}>キャンセル</button>
        <button className="btn" disabled={uploading} onClick={handleSave}>{uploading ? "保存中…" : "保存"}</button>
      </div>
    </>
  );
}
function CautionInfoSheet({ ctx, m, onClose }) {
  const { db, save, confirm } = ctx;
  const cur = db.priceMaster.find(x => x.id === m.id) || m;
  const entries = (cur.cautionNotes || []).slice().sort((a, b) => (b.createdAt || "").localeCompare(a.createdAt || ""));
  const [header, setHeader] = useState(cur.cautionHeader || "");
  function saveHeader() {
    const d = draftOf(db);
    d.priceMaster.find(x => x.id === m.id).cautionHeader = header.trim();
    save(d);
  }
  function del(e) {
    confirm("この記録を削除しますか？", () => {
      const d = draftOf(db);
      const dm = d.priceMaster.find(x => x.id === m.id);
      dm.cautionNotes = (dm.cautionNotes || []).filter(x => x.id !== e.id);
      save(d);
      ebDeleteFile(e.storagePath);
    });
  }
  return (
    <>
      <SheetHead title="注意事項" onClose={onClose} />
      <div className="card-sub" style={{ marginBottom: 12 }}>{cur.name}</div>
      <Field label="見積作成時などに表示する注意書き"><textarea placeholder="例）取付方向に注意。既存レールの寸法要確認。" value={header} onChange={e => setHeader(e.target.value)} onBlur={saveHeader} /></Field>
      <div className="card-sub" style={{ margin: "6px 0 16px" }}>↑ここに書いた内容が、見積作成中やマスタから積み上げる時にそのまま表示されます。</div>
      <label style={{ marginTop: 4 }}>記録（写真・過去の経緯など）</label>
      {entries.length === 0 ? <div className="empty">記録はまだありません。<br />「＋ 記録を追加」から登録してください。</div> : entries.map(e => (
        <div className="cost-entry" key={e.id}>
          <div className="ce-top"><div className="ce-price" style={{ fontSize: 12.5, color: "var(--sub)", fontWeight: 700 }}>{fmtDate(e.createdAt)}</div><button className="icon-btn danger" onClick={() => del(e)}>✕</button></div>
          {e.note && <div className="ce-note">{e.note}</div>}
          <FileEntryPreview e={e} />
        </div>
      ))}
      <div className="sticky-actions"><button className="btn" style={{ width: "100%" }} onClick={() => ctx.open2("cautionEntryForm", { m: cur })}>＋ 記録を追加</button></div>
    </>
  );
}
function CautionEntryFormSheet({ ctx, m, onSaved, existingEntry, onClose }) {
  const { db, save, notice } = ctx;
  const isEdit = !!existingEntry;
  const [note, setNote] = useState(isEdit ? existingEntry.note || "" : "");
  const [uploading, setUploading] = useState(false);
  const fileRef = useRef(null);

  async function handleSave() {
    const file = fileRef.current && fileRef.current.files[0];
    const hasExistingFile = isEdit && existingEntry.fileUrl;
    if (!note.trim() && !file && !hasExistingFile) { notice("内容を入力するか、ファイルを添付してください。"); return; }
    if (file && file.size > MAX_FILE_SIZE) { notice("ファイルサイズが大きすぎます（4MBまで）。写真は少し圧縮してから添付してください。"); return; }
    setUploading(true);
    try {
      let fileMeta = null;
      if (file) fileMeta = await ebUploadFile(file, `cautionNotes/${m.id}`);
      const d = draftOf(db);
      const dm = d.priceMaster.find(x => x.id === m.id);
      if (isEdit) {
        const target = dm.cautionNotes.find(x => x.id === existingEntry.id);
        target.note = note.trim();
        if (fileMeta) Object.assign(target, fileMeta);
      } else {
        dm.cautionNotes = dm.cautionNotes || [];
        dm.cautionNotes.push({ id: uid("caution"), note: note.trim(), fileUrl: null, storagePath: null, fileName: null, fileType: null, ...(fileMeta || {}), createdAt: todayISO() });
      }
      save(d);
      onClose();
      if (onSaved) onSaved();
    } catch (err) { notice("ファイルのアップロードに失敗しました: " + err.message); }
    setUploading(false);
  }
  return (
    <>
      <SheetHead title={isEdit ? "記録を編集" : "記録を追加"} onClose={onClose} />
      <div className="card-sub" style={{ marginBottom: 8 }}>{m.name}</div>
      <Field label="内容"><textarea placeholder="施工上の注意点、過去のトラブル、取扱い上の注意など" value={note} onChange={e => setNote(e.target.value)} /></Field>
      <Field label="ファイル添付（任意・現場写真など）">
        {isEdit && existingEntry.fileUrl && <><FileEntryPreview e={existingEntry} /><div className="card-sub" style={{ marginBottom: 6 }}>↑現在の添付ファイル。差し替える場合だけ下から選んでください。</div></>}
        <input ref={fileRef} type="file" accept="image/*,.pdf" disabled={uploading} />
      </Field>
      <div className="sheet-footer">
        <button className="btn secondary" onClick={onClose}>キャンセル</button>
        <button className="btn" disabled={uploading} onClick={handleSave}>{uploading ? "保存中…" : "保存"}</button>
      </div>
    </>
  );
}
function MasterPickerSheet({ ctx, onAdd, onClose }) {
  const { db, save, notice, open } = ctx;
  const [selected, setSelected] = useState({});
  const [search, setSearch] = useState("");
  const [cat, setCat] = useState("all");
  const roots = catChildren(db, null);
  const cats = [{ id: "all", name: "すべて" }, { id: "よく使う", name: "よく使う" }, ...roots.map(c => ({ id: c.id, name: c.name }))];

  function toggle(id) { setSelected(p => { const n = { ...p }; if (n[id]) delete n[id]; else n[id] = 1; return n; }); }
  let items = db.priceMaster.slice();
  if (cat === "よく使う") items = items.filter(m => findQuotesUsingItem(db, { masterId: m.id, name: m.name }).length > 0);
  else if (cat !== "all") { const allowed = catDescendantIds(db, cat); items = items.filter(m => allowed.includes(m.categoryId)); }
  if (search) items = items.filter(m => m.name.includes(search));

  function Row({ m }) {
    const on = !!selected[m.id];
    const hits = findQuotesUsingItem(db, { masterId: m.id, name: m.name });
    const last = hits[0];
    const recordCount = (m.cautionNotes || []).length;
    return (
      <div className="master-row">
        <div className={`chk${on ? " on" : ""}`} onClick={() => toggle(m.id)}>{on ? "✓" : ""}</div>
        <div className="m-body" onClick={() => toggle(m.id)}>
          <div className="m-name">{m.name}</div>
          <div className="m-sub">単位: {m.unit || "-"}{last ? `・前回 ${fmtYen(last.item.unitPrice)}（${last.project ? last.project.siteName : ""}）` : ""}</div>
          {m.cautionHeader && <div className="caution-line">⚠ {m.cautionHeader}{recordCount ? `　他${recordCount}件` : ""}</div>}
        </div>
        <div className="m-price" onClick={() => toggle(m.id)}>{fmtYen(m.unitPrice)}</div>
        {hits.length > 0 && <button className="icon-btn" onClick={e => { e.stopPropagation(); ctx.open2("itemUsage", { m }); }}>🔍</button>}
      </div>
    );
  }
  function list() {
    if (items.length === 0) return <div className="empty">該当する項目がありません。</div>;
    if (cat === "all") {
      const tree = flattenCategoryTreeDepth(db, null, 0);
      return tree.map(node => {
        const nodeItems = items.filter(m => m.categoryId === node.id);
        if (nodeItems.length === 0) return null;
        return (
          <div key={node.id}>
            <div className="cat-head" style={{ paddingLeft: node.depth * 14 }}>{node.name}</div>
            {nodeItems.slice().sort((a, b) => (b.useCount || 0) - (a.useCount || 0) || a.name.localeCompare(b.name, "ja")).map(m => <Row key={m.id} m={m} />)}
          </div>
        );
      });
    }
    return items.map(m => <Row key={m.id} m={m} />);
  }
  function addSelected() {
    const ids = Object.keys(selected);
    if (ids.length === 0) { notice("項目を選択してください"); return; }
    const d = draftOf(db);
    const newItems = ids.map(id => {
      const m = d.priceMaster.find(x => x.id === id);
      m.useCount = (m.useCount || 0) + 1;
      return { id: uid("it"), name: m.name, unit: m.unit, qty: 1, unitPrice: m.unitPrice, masterId: m.id };
    });
    save(d);
    onClose();
    onAdd(newItems);
  }
  const n = Object.keys(selected).length;

  return (
    <>
      <SheetHead title="マスタから積み上げ" onClose={onClose} />
      <input type="search" value={search} placeholder="項目名で検索" onChange={e => setSearch(e.target.value)} />
      <div className="filter-chips" style={{ marginTop: 10 }}>{cats.map(c => <div key={c.id} className={`chip${cat === c.id ? " active" : ""}`} onClick={() => setCat(c.id)}>{c.name}</div>)}</div>
      <div>{list()}</div>
      <div className="sticky-actions">
        <button className="btn ghost small" style={{ width: "100%", marginBottom: 8 }} onClick={() => open("masterItemEditor", { item: null, onSaved: created => setSelected(p => ({ ...p, [created.id]: 1 })) })}>＋ マスタに新しい項目を登録</button>
        <button className="btn" style={{ width: "100%" }} onClick={addSelected}>{n ? `選択した ${n} 件を追加` : "選択した項目を追加"}</button>
      </div>
    </>
  );
}
